var n=`0835-chana-masala`;var i=`world-0835`;var t=`IN`;var s=`south-asia`;var o=4;var r=40;var g={en:`Chana Masala`,ua:`Чана масала`};var l={en:`Chana Masala is a India dish made with yellow onion, tomato, ginger-garlic paste, canned chickpeas. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Чана масала, страва кухні країни Індія. Основні складники: жовта цибуля, помідор, імбирно-часникова паста, консервований нут. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,210,`g`],[`canola-oil`,45,`ml`],[`tomato`,340,`g`],[`ginger-garlic-paste`,35,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`canned-chickpeas`,640,`g`],[`water`,310,`ml`],[`ground-cumin`,7,`g`],[`ground-coriander`,8,`g`],[`garam-masala`,7,`g`],[`amchur-powder`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`lemon`,1,`pcs`]]}];var h={slug:n,id:i,country:`IN`,region:s,servings:4,minutes:40,title:g,text:l,steps:d};export{t as country,h as default,i as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,g as title};